var _markdown = "\n\n`sa` · 扩展 `default` · SCM 原生命令\n\n共 4 条。写法见 [Lua](/docs/cleo/syntax) / [Redux](/docs/cleo/syntax-redux)。\n\n## 加载 [#加载]\n\n<Opcode id=\"06AE\" name=\"LOAD_GROUP_DECISION_MAKER\" member=\"DecisionMakerGroup.Load\">\n  加载给角色组用的决策器。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      06AE LOAD_GROUP_DECISION_MAKER\n      in: type\n      out: handle\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local handle = loadGroupDecisionMaker(type)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const handle = DecisionMakerGroup.load(type)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 清事件响应 [#清事件响应]\n\n<Opcode id=\"0749\" name=\"CLEAR_GROUP_DECISION_MAKER_EVENT_RESPONSE\" member=\"DecisionMakerGroup.ClearEventResponse\">\n  清掉组决策器对某事件的响应。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0749 CLEAR_GROUP_DECISION_MAKER_EVENT_RESPONSE\n      in: self, event\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      clearGroupDecisionMakerEventResponse(self, event)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      DecisionMakerGroup.clearEventResponse(self, event)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 加事件响应 [#加事件响应]\n\n<Opcode id=\"074A\" name=\"ADD_GROUP_DECISION_MAKER_EVENT_RESPONSE\" member=\"DecisionMakerGroup.AddEventResponse\">\n  按事件配置组反应（任务、好感档、车内 / 步行等）。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      074A ADD_GROUP_DECISION_MAKER_EVENT_RESPONSE\n      in: self, event, taskId, respect, hate, like, dislike, inCar, onFoot\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      addGroupDecisionMakerEventResponse(self, event, taskId, respect, hate, like, dislike, inCar, onFoot)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      DecisionMakerGroup.addEventResponse(self, event, taskId, respect, hate, like, dislike, inCar, onFoot)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 复制 [#复制]\n\n<Opcode id=\"07E6\" name=\"COPY_GROUP_DECISION_MAKER\" member=\"DecisionMakerGroup.Copy\">\n  复制组决策器（进任务清理表；否则用 `065C` 释放）。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      07E6 COPY_GROUP_DECISION_MAKER\n      in: handleOrTemplate\n      out: handle\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local handle = copyGroupDecisionMaker(handleOrTemplate)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const handle = DecisionMakerGroup.copy(handleOrTemplate)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n";
